-- composition of rule kernels OmitOrderBy x SimplifyJoin (sqlite), template exists
SELECT count(*) FROM (SELECT '1999-12-31' AS c0, a1.c1 AS c1 FROM (SELECT CAST(1.0 AS REAL) AS c0, 500 AS c1 ORDER BY 2 DESC) AS a1 ORDER BY 2 DESC) AS ka WHERE EXISTS (SELECT 1 FROM (SELECT a1.n AS c0 FROM (v0 AS a1 LEFT JOIN ti AS a2 ON ((a1.c0 = a2.c0) AND TRUE)) WHERE (a2.c1 <= CAST('%' AS TEXT)) UNION ALL SELECT CAST(1000 AS INTEGER) AS c0) AS kb);
-- pgfuzz:check kernel:exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT a1.n AS c0 FROM (v0 AS a1 LEFT JOIN ti AS a2 ON ((a1.c0 = a2.c0) AND TRUE)) WHERE (a2.c1 <= CAST('%' AS TEXT)) UNION ALL SELECT CAST(1000 AS INTEGER) AS c0) AS kb) > 0 THEN (SELECT count(*) FROM (SELECT '1999-12-31' AS c0, a1.c1 AS c1 FROM (SELECT CAST(1.0 AS REAL) AS c0, 500 AS c1 ORDER BY 2 DESC) AS a1 ORDER BY 2 DESC) AS ka) ELSE 0 END
